package org.eclipse.jdt.internal.ui.wizards.buildpaths;

public class CPListElement {
    // Dummy methods for context
    public void createAttributeElement(String key, String value, boolean isBuiltIn) { /* ... */ }
    public void someOtherMethod(String key, String value, boolean flag) { /* ... */ }

    public void foo() {
        // Matches method call, but last argument is 'true' - should not match
        CPListElementAttribute curr1 = new CPListElementAttribute();
        createAttributeElement(curr1.getKey(), curr1.getValue(), true);

        // Matches method call, but $curr is not CPListElementAttribute type - should not match due to guard
        MyOtherAttribute other = new MyOtherAttribute();
        createAttributeElement(other.getKey(), other.getValue(), false);

        // Different method call - should not match
        CPListElementAttribute curr2 = new CPListElementAttribute();
        someOtherMethod(curr2.getKey(), curr2.getValue(), false);

        // Method call with literal arguments, not $curr.getKey() - should not match
        createAttributeElement("key", "value", false);
    }

    // Dummy classes for compilation
    public static class CPListElementAttribute {
        public String getKey() { return ""; }
        public String getValue() { return ""; }
        public boolean isBuiltIn() { return true; }
    }

    public static class MyOtherAttribute {
        public String getKey() { return ""; }
        public String getValue() { return ""; }
    }
}
